    function paintSelectedHistoryStatus(){const caption=$('terminal-selected-history-status');if(caption)caption.textContent=selectedHistoryStatus(history(),state.selectedHistoryResult,state.selectedHistoryStatus);const button=host.querySelector('[data-terminal-selected-history]');if(button)button.disabled=state.selectedHistoryStatus.state==='loading'||state.selectedHistoryStatus.state==='blocked'||!!state.selectedHistoryLoader?.snapshot().status.sourceBlocked;const proof=$('terminal-selected-history-proof');if(proof)proof.innerHTML=selectedHistoryProof();}
    function stopSelectedHistory(){if(state.selectedDayTimer!==null){clearTimeout(state.selectedDayTimer);state.selectedDayTimer=null;}state.selectedHistoryStamp=null;state.selectedHistoryEpoch++;state.selectedHistoryLoader?.cancel();}
    function refreshSelectedPrice(){const h=history(),a=analysis();if(!h||!a||state.mode!=='price')return;if(state.interval==='1d'&&state.priceHistoryKey===h.key){const data=priceData(h);state.priceClosedSeries=data.series;paintCandle();const coverage=$('terminal-price-coverage');if(coverage)coverage.textContent=data.daily.length+' ngày đã đóng thực tế · '+data.out.excluded.length+' kỳ biên hoặc thiếu ngày được loại khỏi nến hoàn chỉnh. Giá và volume: Binance / USDT; EMA tính từ toàn bộ lịch sử ngày liên tục trước khi cắt cửa sổ.';}else renderPrice(h,a,null);paintSelectedHistoryStatus();}
    function syncSelectedHistory(h,{forceVerify=false}={}){
      if(!G.FlowSelectedHistory?.create||!h)return;
      const visible=!host.hidden&&!document.hidden&&state.mode==='price';if(!visible){stopSelectedHistory();return;}
      if(state.selectedDayTimer===null){state.selectedDayTimer=setTimeout(()=>{state.selectedDayTimer=null;syncSelectedHistory(history());},Math.max(1000,(Math.floor(Date.now()/DAY)+1)*DAY+5000-Date.now()));state.selectedDayTimer?.unref?.();}
      if(!state.selectedHistoryLoader)state.selectedHistoryLoader=G.FlowSelectedHistory.create({fetchImpl:options.selectedHistoryFetcher||options.fetcher||fetch,transport:options.selectedHistoryTransport,onStatus:value=>{if(value.instrument!==history()?.instrument)return;state.selectedHistoryStatus=value;paintSelectedHistoryStatus();}});
      const stampKey=h.key+'|'+h.asOf+'|'+h.fetchedAt+'|'+h.bars.length+'|'+Math.floor(Date.now()/DAY);if(!forceVerify&&state.selectedHistoryStamp===stampKey&&state.selectedHistoryParent===h)return;
      state.selectedHistoryEpoch++;const epoch=state.selectedHistoryEpoch;state.selectedHistoryStamp=stampKey;if(state.selectedHistoryParent!==h){state.selectedHistoryResult=null;state.selectedHistoryParent=h;}state.selectedHistoryStatus={state:'loading',instrument:h.instrument};paintSelectedHistoryStatus();
      state.selectedHistoryLoader.ensure(h,{forceVerify}).then(result=>{if(epoch!==state.selectedHistoryEpoch||history()!==h||host.hidden||document.hidden||state.mode!=='price')return;state.selectedHistoryResult=result;state.selectedHistoryStatus=state.selectedHistoryLoader.snapshot().status;refreshSelectedPrice();}).catch(error=>{if(epoch!==state.selectedHistoryEpoch||history()!==h)return;state.selectedHistoryStatus={...state.selectedHistoryLoader.snapshot().status,error:error.message};paintSelectedHistoryStatus();});
    }
    function renderSearch(){const rows=rankTokens(state.analyses.map(a=>({key:a.key,base:a.base,instrument:a.instrument,quote30:a.metrics.quote30})),state.query,state.query?12:7);$('terminal-search-results').innerHTML=rows.length?rows.map(r=>'<button role="listitem" data-terminal-key="'+esc(r.key)+'" class="'+(r.key===state.key?'selected':'')+'">'+esc(r.base)+'<small>Binance / USDT</small></button>').join(''):pill('Không có cặp trong danh mục đã thu thập');}
