      const status=state.candleSnapshot?.status||{};
      if(projection.appended){const bar=projection.bar,fresh=status.state==='live'&&!projection.stale;return session+'Nến đang hình thành · chưa dùng nghiên cứu · '+day(bar.time)+' UTC · Close '+fmt(bar.close,10)+' USDT. '+(fresh?'Đang nhận kline gốc Binance (nhịp nguồn khoảng 2 giây).':'Luồng trễ hoặc tạm dừng; giữ nguyên số đo đã nhận.')+' Sự kiện '+stamp(bar.eventTime)+' · nhận '+stamp(bar.receivedAt)+'. EMA tạm tính từ EMA nến đóng cuối; không cộng lặp mỗi lần cập nhật.';}
      if(projection.reason==='history_gap')return session+'Chưa ghép nến trực tiếp: lịch sử lưu thiếu '+projection.missingDays+' ngày UTC trước hôm nay. Không nối qua ngày thiếu hoặc tự điền nến. Luồng kline vẫn được ghi thời điểm riêng.';
