ineChart(rankSeries,groups.map((g,i)=>({key:'g'+i,label:'Hạng '+g.label})),{label:'HBAR: tổng số dư theo hạng tại từng mốc, có thể đổi thành viên',unit:'HBAR',maxGapMs:1.5*DAY})+'<p class="terminal-caption">Biểu đồ phụ xếp hạng lại ở từng ngày. Thành viên có thể thay đổi; không dùng thay cho lịch sử cùng địa chỉ hoặc kết luận mua ròng.</p></details><details class="terminal-proof"><summary>Phạm vi lịch sử và bằng chứng nguồn</summary><pre>'+esc(JSON.stringify({asset:snapshot.asset,source:snapshot.source,coverage:latest.coverage,cohorts:comparison?.groups},null,2))+'</pre>'+observations.flatMap(o=>o.provenance||[]).slice(0,12).map(p=>'<p>'+safeLink(p.url||p.endpoint||'',p.id||'Hedera Mirror Node')+(p.sha256?'<br><code>'+esc(p.sha256)+'</code>':'')+'</p>').join('')+'</details>';
      const boundPanel='<div class="terminal-holder-controls"><label>Khoảng số dư của nhóm<select aria-label="Khoảng số dư của nhóm" data-terminal-holder-bound-group>'+groups.map((g,i)=>'<option value="'+i+'" '+(g===boundGroup?'selected':'')+'>'+g.label+'</option>').join('')+'</select></label>'+pill('Cận trên / dưới · không dùng trung điểm','partial')+'</div>'+lineChart(boundSeries,[{key:'lower',label:'Cận dưới số dư'},{key:'upper',label:'Cận trên số dư'}],{label:'Khoảng số dư có thể của cùng nhóm địa chỉ gốc',unit:'HBAR',maxGapMs:1.5*DAY})+'<p class="terminal-caption">Địa chỉ vắng trong danh mục phân trang được giới hạn từ 0 đến dưới 1 triệu HBAR. Hai đường là cận dữ liệu, không phải số dư đo chính xác. Khi quan sát đầy đủ, hai cận trùng nhau.</p>';
      $('terminal-holder-body').querySelector('.terminal-proof')?.insertAdjacentHTML('beforebegin',boundPanel);
      if(state.holderExcludeKnown)$('terminal-holder-body').insertAdjacentHTML('afterbegin','<p class="terminal-caption">Đang ẩn và xếp hạng lại sau khi loại hạ tầng theo danh sách chính thức tại '+esc(HH.CLASSIFICATION_AS_OF)+'. Nhãn này áp dụng hồi cứu, chưa phải nhãn đã biết tại từng ngày lịch sử và không dùng để backtest chủ thể.</p>');
