      const report=D.summary(s),asset=D.findExactNativeAsset(s,state.perpNative||'BTC'),active=(s.assets||[]).filter(z=>!z.isDelisted);
      const chosen=(asset&&!asset.isDelisted?asset:null)||active.find(z=>z.nativeName==='BTC')||active[0];
